package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.sun.net.httpserver.HttpServer;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/** Runs the real gateway over real HTTP against a stand-in provider on a local port. */
class HttpPaymentGatewayTest {

    private HttpServer provider;
    private HttpPaymentGateway gateway;
    private final AtomicReference<String> method = new AtomicReference<>();
    private final AtomicReference<String> path = new AtomicReference<>();
    private final AtomicReference<String> contentType = new AtomicReference<>();
    private final AtomicReference<String> body = new AtomicReference<>();
    private volatile int status = 200;
    private volatile String answer = "{\"status\":\"approved\"}";

    @BeforeEach
    void startProvider() throws Exception {
        provider = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        provider.createContext("/", exchange -> {
            method.set(exchange.getRequestMethod());
            path.set(exchange.getRequestURI().getPath());
            contentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            body.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
            var bytes = answer.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
            if (bytes.length > 0) exchange.getResponseBody().write(bytes);
            exchange.close();
        });
        provider.start();
        var client = RestClient.builder().baseUrl("http://127.0.0.1:" + provider.getAddress().getPort()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopProvider() {
        provider.stop(0);
    }

    @Test
    void sends_the_authorization_as_a_json_post_to_the_authorizations_endpoint() {
        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        assertThat(method.get()).isEqualTo("POST");
        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        assertThat(body.get()).isEqualTo("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_answer_is_an_approval() {
        answer = "{\"status\":\"approved\"}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_a_decline() {
        answer = "{\"status\":\"declined\"}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        answer = "{\"id\":\"auth_9\",\"status\":\"approved\",\"risk\":{\"score\":3}}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unrecognised_status_is_never_treated_as_an_approval() {
        answer = "{\"status\":\"pending\"}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_an_approval() {
        answer = "{\"decision\":\"approved\"}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_is_a_decline_whatever_the_body_says() {
        status = 402;
        answer = "{\"status\":\"approved\",\"error\":\"card_refused\"}";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_with_an_empty_body_is_a_decline() {
        status = 402;
        answer = "";

        assertThat(gateway.authorize("ORD-1", eur())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_as_a_failure_not_a_decline() {
        status = 400;
        answer = "{\"error\":\"bad_request\"}";

        assertThatThrownBy(() -> gateway.authorize("ORD-1", eur()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        status = 503;
        answer = "";

        assertThatThrownBy(() -> gateway.authorize("ORD-1", eur()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    private static Money eur() {
        return new Money(new BigDecimal("10"), "EUR");
    }
}
